package com.erudit.user;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import com.erudit.user.model.SocialModels.*;import com.erudit.user.repository.SocialRepository;import com.erudit.user.service.SocialService;import java.util.*;import org.junit.jupiter.api.Test;
class SocialServiceTest {@Test void validatesAndDelegatesSocialOperations(){var repository=mock(SocialRepository.class);var service=new SocialService(repository);UUID a=UUID.randomUUID(),b=UUID.randomUUID(),request=UUID.randomUUID();when(repository.request(a,b)).thenReturn(request);when(repository.friends(a,0,20)).thenReturn(List.of(new PublicUser(b,"B")));assertThat(service.request(a,b)).isEqualTo(request);assertThat(service.friends(a,0,20)).hasSize(1);service.decide(b,request,"accept");verify(repository).decide(b,request,true);service.remove(a,b);service.revoke(a,b);assertThatThrownBy(()->service.request(a,a)).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->service.friends(a,0,51)).isInstanceOf(IllegalArgumentException.class);}}
